  'United States': '🇺🇸', 'Uruguay': '🇺🇾', 'Uzbekistan': '🇺🇿', 'Venezuela': '🇻🇪', 'Vietnam': '🇻🇳',
  'Wales': '🏴󠁧󠁢󠁷󠁬󠁳󠁿', 'Yemen': '🇾🇪', 'Zambia': '🇿🇲', 'Zimbabwe': '🇿🇼',
  'Dominican Republic': '🇩🇴', 'Korea': '🇰🇷'
};

const getFlag = name => flags[name] || '🚩';

const API_KEY = 'YOUR_API_FOOTBALL_KEY';

const fetchScorers = async (match) => {
  const homeId = match.teams.home.id;
  const homeScorers = [];
  const awayScorers = [];
  let events = [];
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://v3.football.api-sports.io/fixtures/events?fixture=${match.fixture.id}`,
      headers: { 'x-apisports-key': API_KEY },
      json: true,
    });
    events = (res && res.response) || [];
  } catch (e) {
    return { homeScorers, awayScorers };
  }
  const goals = events.filter(e => e && e.type === 'Goal' && e.detail !== 'Missed Penalty');
  goals.sort((a, b) => {
    const ae = a.time.elapsed || 0, be = b.time.elapsed || 0;
    if (ae !== be) return ae - be;
    return (a.time.extra || 0) - (b.time.extra || 0);
  });
  for (const e of goals) {
    const player = (e.player && e.player.name) || 'Unknown';
    const el = e.time.elapsed;
    const extra = e.time.extra;
    const minute = `${el != null ? el : ''}${extra ? '+' + extra : ''}'`;
    const isPen = e.detail === 'Penalty';
    const isOwn = e.detail === 'Own Goal';
    const tag = isPen ? ' (P)' : (isOwn ? ' (OG)' : '');
    const label = `${player} ${minute}${tag}`;
    const teamId = e.team && e.team.id;
    let creditHome = teamId === homeId;
    if (isOwn) creditHome = !creditHome;
    (creditHome ? homeScorers : awayScorers).push(label);
  }
  return { homeScorers, awayScorers };
};

const header = '*🏆 FIFA WORLD CUP 2026 ⚽*\n*TODAY RESULTS*';

const matchBlocks = [];
for (const match of fixtures) {
  const home = match.teams.home.name;
  const away = match.teams.away.name;
  const status = match.fixture.status.short;
  const homeGoals = match.goals.home;
  const awayGoals = match.goals.away;

  let scoreText;
  if (FINISHED_STATUSES.includes(status)) {
    const suffix = status === 'AET' ? ' AET' : status === 'PEN' ? ' PEN' : '';
    scoreText = `${homeGoals}-${awayGoals}${suffix}`;
  } else if (status === 'NS') {
    scoreText = 'Not started';
  } else if (status === 'SUSP') {
    scoreText = 'Suspended';
  } else if (CANCELLED_STATUSES.includes(status)) {
    scoreText = status === 'PST' ? 'Postponed' : 'Cancelled';
  } else {
    scoreText = 'In Progress';
  }

  let block = `${getFlag(home)} ${home} (${scoreText}) ${away} ${getFlag(away)}`;

  if (FINISHED_STATUSES.includes(status) && ((homeGoals || 0) + (awayGoals || 0)) > 0) {
    const { homeScorers, awayScorers } = await fetchScorers(match);
    const parts = [];
    if (homeScorers.length) parts.push(homeScorers.join('\n'));
    if (awayScorers.length) parts.push(awayScorers.join('\n'));
    if (parts.length) block += `\n${parts.join('\n-\n')}`;
  }

  matchBlocks.push(block);
}

const MAX_CHARS = 1500;
const chunks = [];
let current = `${header}\n\n${matchBlocks[0] || ''}`;

for (let i = 1; i < matchBlocks.length; i++) {
  const block = matchBlocks[i];
  const testMsg = current + '\n\n' + block;
  if (testMsg.length > MAX_CHARS) {
    chunks.push(current);
    current = block;
  } else {
    current = testMsg;
  }
}
if (current) chunks.push(current);

const output = [];
for (const to of recipients) {
  for (const message of chunks) {
    output.push({ json: { message, to } });
  }
}
return output;
